cat > /tmp/opencode/test-dispatcher.js <<'EOF'
const { deliver } = require('/workspace/src/dispatcher.js');

function mockIo(responses) {
  const calls = [];
  return {
    calls,
    io: {
      async post(url, body, opts) {
        calls.push({ url, body, opts });
        return responses.shift();
      },
      async sleep(ms) { calls.push({ sleep: ms }); },
    },
  };
}

(async () => {
  // Case 1: 502 then 200 -> retries once, returns 200, idempotency key on every attempt
  {
    const { io, calls } = mockIo([{ status: 502 }, { status: 200 }]);
    const res = await deliver(io, { id: 'evt_123', type: 'charge' });
    console.log('case1 res:', JSON.stringify(res), '| post calls:', calls.filter(c => c.url).length);
    console.log('case1 keys:', JSON.stringify(calls.filter(c => c.url).map(c => c.opts.headers)));
  }
  // Case 2: 4xx -> no retry
  {
    const { io, calls } = mockIo([{ status: 400 }]);
    const res = await deliver(io, { id: 'evt_456' });
    console.log('case2 res:', JSON.stringify(res), '| post calls:', calls.filter(c => c.url).length);
  }
  // Case 3: all 5xx -> returns 502 after 5 attempts with backoff sleeps
  {
    const { io, calls } = mockIo([{ status: 502 }, { status: 503 }, { status: 500 }, { status: 504 }, { status: 502 }]);
    const res = await deliver(io, { id: 'evt_789' });
    const posts = calls.filter(c => c.url);
    const sleeps = calls.filter(c => c.sleep);
    console.log('case3 res:', JSON.stringify(res), '| posts:', posts.length, '| sleeps:', JSON.stringify(sleeps.map(s => s.sleep)));
  }
  // Case 4: event without id -> stable key derived from serialization
  {
    const { io, calls } = mockIo([{ status: 502 }, { status: 200 }]);
    await deliver(io, { type: 'charge', amount: 100 });
    const keys = calls.filter(c => c.url).map(c => c.opts.headers['Idempotency-Key']);
    console.log('case4 keys (should be identical):', JSON.stringify(keys));
  }
})();
EOF
